import{_ as o,H as r,f as t,i as s}from"./chunks/framework.DLd0CbzH.js";const p=JSON.parse('{"title":"Бизнес-процесс: Многостадийный парсинг данных","description":"","frontmatter":{},"headers":[],"relativePath":"business-processes/parsing-process.md","filePath":"business-processes/parsing-process.md"}'),n={name:"business-processes/parsing-process.md"};function a(l,e,i,c,d,u){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="бизнес-процесс-многостадииныи-парсинг-данных" tabindex="-1">Бизнес-процесс: Многостадийный парсинг данных <a class="header-anchor" href="#бизнес-процесс-многостадииныи-парсинг-данных" aria-label="Permalink to &quot;Бизнес-процесс: Многостадийный парсинг данных&quot;">​</a></h1><blockquote><p><strong>Устарело / superseded.</strong> Каноничный источник — <code>docs/03_Dev/Architecture.md</code> и <code>docs/03_Dev/Procurement_Lifecycle.md</code> (актуальная краткая версия — <code>docs/workflow/parsing-process.md</code>). Имена таблиц ниже не соответствуют текущему коду.</p></blockquote><p>Процесс разделен на 4 стадии, чтобы минимизировать затраты на вычислительные ресурсы и API токены, отсеивая нерелевантные данные на ранних этапах.</p><h2 id="стадия-1-сбор-ссылок-collector" tabindex="-1">Стадия 1: Сбор ссылок (Collector) <a class="header-anchor" href="#стадия-1-сбор-ссылок-collector" aria-label="Permalink to &quot;Стадия 1: Сбор ссылок (Collector)&quot;">​</a></h2><p><strong>Цель:</strong> Получение списка новых извещений из ЕИС.</p><ul><li><strong>Вход:</strong> Ссылка на результаты расширенного поиска ЕИС (с настроенными фильтрами).</li><li><strong>Действие:</strong> Обход страниц поиска, сбор номеров извещений (<code>reg_number</code>), ссылок на карточки и трех ключевых дат (публикация, обновление, окончание подачи).</li><li><strong>Результат:</strong> Записи в таблице <code>platform_parser_map_urls</code>.</li></ul><h2 id="стадия-2-индексация-документов-document-indexer" tabindex="-1">Стадия 2: Индексация документов (Document Indexer) <a class="header-anchor" href="#стадия-2-индексация-документов-document-indexer" aria-label="Permalink to &quot;Стадия 2: Индексация документов (Document Indexer)&quot;">​</a></h2><p><strong>Цель:</strong> Получение списка всех вложенных файлов закупки.</p><ul><li><strong>Вход:</strong> Карточка закупки.</li><li><strong>Действие:</strong> Переход в раздел «Документы», сбор прямых ссылок на скачивание файлов и их названий.</li><li><strong>Фильтрация:</strong> Предварительная фильтрация по именам файлов (поиск ключевых слов &quot;смета&quot;, &quot;лср&quot;, &quot;локальный&quot;).</li><li><strong>Результат:</strong> Записи в таблице <code>platform_parser_map_documents</code>.</li></ul><h2 id="стадия-3-ии-скрининг-ai-screening" tabindex="-1">Стадия 3: ИИ-скрининг (AI Screening) <a class="header-anchor" href="#стадия-3-ии-скрининг-ai-screening" aria-label="Permalink to &quot;Стадия 3: ИИ-скрининг (AI Screening)&quot;">​</a></h2><p><strong>Цель:</strong> Быстрая проверка: является ли файл сметой. Самый важный этап экономии ресурсов.</p><ul><li><strong>Действие:</strong> * Для <strong>Excel</strong>: отправка первых 50-100 строк (в формате HTML) в Gemini. <ul><li>Для <strong>PDF/Сканов</strong>: отправка только первой страницы документа.</li></ul></li><li><strong>Запрос к ИИ:</strong> «Является ли этот документ сметой СМР? Какова итоговая сумма?».</li><li><strong>Результат:</strong> Обновление статуса в <code>ai_analysis_report</code>. Если <code>is_smeta = true</code>, закупка переходит на следующую стадию.</li></ul><h2 id="стадия-4-глубокии-парсинг-full-data-extraction" tabindex="-1">Стадия 4: Глубокий парсинг (Full Data Extraction) <a class="header-anchor" href="#стадия-4-глубокии-парсинг-full-data-extraction" aria-label="Permalink to &quot;Стадия 4: Глубокий парсинг (Full Data Extraction)&quot;">​</a></h2><p><strong>Цель:</strong> Полное извлечение всех позиций сметы и создание записей в БД.</p><ul><li><strong>Действие:</strong> * Чанковая обработка всего файла (по 80 строк). <ul><li>Распознавание обоснований, наименований работ, единиц измерения, объемов и стоимостей.</li><li>Сопоставление данных с разделами сметы.</li></ul></li><li><strong>Результат:</strong> Заполнение таблиц <code>orders</code> и <code>order_lots</code>, создание детализированного списка позиций сметы для анализа пользователем.</li></ul>',15)])])}const _=o(n,[["render",a]]);export{p as __pageData,_ as default};
